import { index, jsonb, pgSchema, text, timestamp, unique, uuid } from 'drizzle-orm/pg-core';
import { v7 as uuidv7 } from 'uuid';

/** Every table lives in schema `app` (spec §8.1). Drizzle's ledger lives in schema `drizzle`. */
export const app = pgSchema('app');

// Conventions for every table: UUIDv7 ids generated by the app, timestamptz audit columns.
const id = () =>
  uuid('id')
    .primaryKey()
    .$defaultFn(() => uuidv7());
const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/** Base table: the app's own record of each person, provisioned from token claims. */
export const users = app.table(
  'users',
  {
    id: id(),
    entraTenantId: uuid('entra_tenant_id').notNull(),
    entraObjectId: uuid('entra_object_id').notNull(),
    email: text('email'),
    displayName: text('display_name'),
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [unique('users_entra_identity_key').on(t.entraTenantId, t.entraObjectId)],
);

/** Base table: append-only history of who did what (enforced by grants, spec §8.5). */
export const auditEvents = app.table(
  'audit_events',
  {
    id: id(),
    occurredAt: timestamp('occurred_at', { withTimezone: true }).notNull().defaultNow(),
    actorUserId: uuid('actor_user_id').references(() => users.id),
    action: text('action').notNull(),
    entityType: text('entity_type').notNull(),
    entityId: uuid('entity_id'),
    data: jsonb('data').$type<Record<string, unknown>>().notNull().default({}),
    requestId: text('request_id'),
    traceId: text('trace_id'),
  },
  (t) => [index('audit_events_entity_idx').on(t.entityType, t.entityId, t.occurredAt.desc())],
);

/** Reference feature: copy this table's shape for real features, then delete it. */
export const notes = app.table(
  'notes',
  {
    id: id(),
    ownerId: uuid('owner_id')
      .notNull()
      .references(() => users.id),
    title: text('title').notNull(),
    body: text('body').notNull().default(''),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('notes_owner_created_idx').on(t.ownerId, t.createdAt.desc())],
);
